// Lightweight original Canvas adaptation of the wave-background pattern seen on 21st.dev.
(()=>{const canvas=document.querySelector('#wave-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');let w,h,visible=true;function resize(){w=canvas.clientWidth;h=canvas.clientHeight;const d=Math.min(devicePixelRatio||1,1.5);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0)}resize();new ResizeObserver(resize).observe(canvas);new IntersectionObserver(([entry])=>{visible=entry.isIntersecting}).observe(canvas);let last=0;function draw(t){if(visible&&(!reduced.matches||!last)&&t-last>33){last=t;ctx.clearRect(0,0,w,h);for(let i=0;i<7;i++){ctx.beginPath();for(let x=0;x<w+10;x+=10){const y=h*.63+Math.sin(x/w*5+t*.00022+i*.37)*60+Math.cos(x/w*3+i)*30+i*17;ctx.lineTo(x,y)}ctx.strokeStyle=['#a461ee','#ee75c4','#75dce6'][i%3];ctx.globalAlpha=.08;ctx.lineWidth=1;ctx.stroke()}ctx.globalAlpha=1}requestAnimationFrame(draw)}requestAnimationFrame(draw);document.addEventListener('pointermove',e=>{const card=e.target.closest('.card');if(card){const r=card.getBoundingClientRect();card.style.setProperty('--mx',`${e.clientX-r.left}px`);card.style.setProperty('--my',`${e.clientY-r.top}px`)}})})();
